if(tipoF==='ano'){var s=$('#ano-sel'),cal=$('#ano-cal'),zoom=$('#ano-zoom');var c='';for(var d=0;d<365;d++)c+='<i'+(d===364?' class="ult"':'')+'></i>';cal.innerHTML=c;var niveis=[[L('1 ano','1 year'),365*86400],[L('Último dia (31/12)','Last day (Dec. 31)'),86400],[L('Última hora','Last hour'),3600],[L('Último minuto','Last minute'),60]];zoom.innerHTML=niveis.map(function(n){return'<div class="zl"><span>'+n[0]+'</span><span class="zb"><i></i></span><b></b></div>';}).join('');var upd=function(){var q=parseInt(s.value,10),selv=q*1e18,exp=434e9,seg=365*24*3600*exp/(selv+exp);$('#ano-v').textContent=q+L(q===1?' quintilhão':' quintilhões',' quintillion');$('#ano-exp').style.width=Math.max(.3,100*exp/(selv+exp))+'%';niveis.forEach(function(n,i){var pc=100*seg/n[1],z=zoom.children[i];z.querySelector('i').style.width=Math.min(100,pc)+'%';z.querySelector('b').textContent=pc>=0.1?dec(pc.toFixed(pc>=10?0:1))+'%':L('invisível','invisible');});var ini=60-seg,hh=Math.floor(ini);cal.dataset.hora='';$('#ano-txt').dataset.ini='23:59:'+String(Math.max(0,hh)).padStart(2,'0');var dur=seg>=1?dec(seg.toFixed(1))+L(' segundos',' seconds'):(seg*1000).toFixed(0)+L(' milissegundos',' milliseconds');$('#ano-txt').innerHTML=EN?'Animals bred for exploitation would take up <strong>'+dur+'</strong> of the year: they would start to appear on <strong>December 31, at '+$('#ano-txt').dataset.ini+'</strong>. All the rest of the year would belong to animals in the wild.':'Os animais criados para exploração seriam <strong>'+dur+'</strong> do ano: eles começariam a aparecer em <strong>31 de dezembro, às '+$('#ano-txt').dataset.ini+'</strong>. Todo o resto do ano seria dos animais na natureza.';};s.addEventListener('input',upd);upd();}
if(tipoF==='duvida'){var upd2=function(){var p=$('#dv-p').value/100,h=+$('#dv-h').value,c=+$('#dv-c').value;$('#dv-pv').textContent=Math.round(p*100)+'%';$('#dv-hv').textContent=h;$('#dv-cv').textContent=c;$('#dv-a1').textContent=L('Custo: ','Cost: ')+c+L(' (nossa precaução)',' (our precaution)');$('#dv-a2').textContent=L('Custo: ','Cost: ')+c+L(' (precaução desnecessária)',' (unnecessary precaution)');$('#dv-b1').textContent=L('Dano: ','Harm: ')+h+L(' (ele é prejudicado)',' (they are harmed)');$('#dv-b2').textContent=L('Custo: 0','Cost: 0');var ea=c,eb=p*h,out=$('#dv-res');grafico($('#dv-graf'),[[L('Tratar como senciente','Treat as sentient'),ea,num(ea),ea<=eb?'bom':'mau'],[L('Tratar como objeto','Treat as an object'),eb,num(eb),ea<=eb?'mau':'bom']],100);out.className='fb '+(ea<=eb?'ok':'no');out.innerHTML=L('Custo esperado de tratar como senciente: <strong>','Expected cost of treating as sentient: <strong>')+ea.toFixed(1)+L('</strong>. Custo esperado de tratar como objeto: <strong>','</strong>. Expected cost of treating as an object: <strong>')+eb.toFixed(1)+'</strong>. '+(ea<=eb?L('A precaução é a melhor escolha.','Precaution is the better choice.'):L('Com estes números, a precaução custaria mais do que o dano esperado. Note que, para a maioria das práticas (como comer ou não um animal), o custo da precaução é baixo e o dano possível é enorme.','With these numbers, precaution would cost more than the expected harm. Note that for most practices (such as whether or not to eat an animal), the cost of precaution is low and the possible harm is enormous.'));};$$('#dv-p,#dv-h,#dv-c').forEach(function(x){x.addEventListener('input',upd2);});upd2();}
if(tipoF==='morte'){var ex=$('#dm-ex');var upd3=function(){var a=+$('#dm-a').value,v=+$('#dm-v').value,q=$('#dm-q').value/100;$('#dm-qv').textContent=num(q,2);var perd=Math.max(0,v-a),avaq=perd*q,pct=v>0?Math.min(100,100*a/v):0;var vd=$('#dm-vida').children;vd[0].style.width=pct+'%';vd[1].style.width=(100-pct)+'%';$('#dm-res').innerHTML=EN?'Years of life lost: <strong>'+num(perd)+'</strong>. QALYs lost: <strong>'+num(avaq)+'</strong>. The individual lived '+num(pct)+'% of the life they could have had. The earlier the death, the greater the loss, even if it is painless.':'Anos de vida perdidos: <strong>'+num(perd)+'</strong>. AVAQs perdidos: <strong>'+num(avaq)+'</strong>. O indivíduo viveu '+num(pct)+'% da vida que poderia ter. Quanto mais cedo a morte, maior a perda, mesmo que ela seja indolor.';};ex.addEventListener('change',function(){var o=ex.selectedOptions[0];if(o.dataset.a){$('#dm-a').value=o.dataset.a;$('#dm-v').value=o.dataset.v;}upd3();});$$('#dm-a,#dm-v,#dm-q').forEach(function(x){x.addEventListener('input',upd3);});upd3();}
if(tipoF==='prior'){var g=function(id){return Math.max(0,+$('#'+id).value||0);};var upd4=function(){var r=['a','b'].map(function(k){var n=g('p'+k+'-n'),gr=g('p'+k+'-g'),t=Math.min(g('p'+k+'-t'),n),b=g('p'+k+'-b'),pe=g('p'+k+'-p');return{grav:n*gr,bem:t*b,neg:1/(1+pe)};});var o=$('#pr-res');var pc=function(x,y){var m=Math.max(x,y)||1;return[100*x/m,100*y/m];};var g1=pc(r[0].grav,r[1].grav),g2=pc(r[0].bem,r[1].bem),g3=pc(r[0].neg,r[1].neg);var gv=L('Gravidade','Severity'),bf=L('Benefício','Benefit'),ng=L('Negligência','Neglect'),mr=L('maior','higher');grafico($('#pr-graf'),[[gv+' · A',g1[0],fmt(r[0].grav)],[gv+' · B',g1[1],fmt(r[1].grav),'mau'],[bf+' · A',g2[0],fmt(r[0].bem)],[bf+' · B',g2[1],fmt(r[1].bem),'mau'],[ng+' · A',g3[0],r[0].neg>=r[1].neg?mr:''],[ng+' · B',g3[1],r[1].neg>r[0].neg?mr:'','mau']],100);var mg=r[0].grav>=r[1].grav?'A':'B',mb=r[0].bem>=r[1].bem?'A':'B',mn=r[0].neg>=r[1].neg?'A':'B';o.innerHTML=EN?'<strong>Total severity</strong> (victims × how bad): A = '+fmt(r[0].grav)+', B = '+fmt(r[1].grav)+' → more severe: '+mg+'.<br><strong>Benefit from this resource</strong> (victims helped × improvement): A = '+fmt(r[0].bem)+', B = '+fmt(r[1].bem)+' → greater benefit: '+mb+'.<br><strong>Neglect</strong>: more neglected: '+mn+'. '+(mg!==mb?'Notice: the most severe problem is not necessarily where the resource does the most good. The book discusses how to weigh these criteria.':''):'<strong>Gravidade total</strong> (vítimas × quão ruim): A = '+fmt(r[0].grav)+', B = '+fmt(r[1].grav)+' → mais grave: '+mg+'.<br><strong>Benefício com este recurso</strong> (vítimas ajudadas × melhora): A = '+fmt(r[0].bem)+', B = '+fmt(r[1].bem)+' → maior benefício: '+mb+'.<br><strong>Negligência</strong>: mais negligenciado: '+mn+'. '+(mg!==mb?'Repare: o problema mais grave não é necessariamente onde o recurso faz mais bem. O livro discute como pesar esses critérios.':'');};$$('input',F).forEach(function(x){x.addEventListener('input',upd4);});upd4();}
function sequencia(caixa,cont,itens,monta_){var i=0,pts=0;var prox=function(){if(i>=itens.length){caixa.innerHTML='<p class="placar">'+L('Você acertou '+pts+' de '+itens.length+'.','You got '+pts+' of '+itens.length+' right.')+'</p><p><button type="button" class="btn">'+L('Recomeçar','Start over')+'</button></p>';$('button',caixa).addEventListener('click',function(){i=0;pts=0;prox();});cont.textContent='';return;}
var it=monta_(itens[i]);caixa.innerHTML='<p class="qp">'+esc(it.p)+'</p><ul class="ops">'+it.ops.map(function(o){return'<li><button type="button" class="op" data-ok="'+(o===it.certa?1:0)+'">'+esc(o)+'</button></li>';}).join('')+'</ul><p class="fb" hidden data-expl="'+esc(it.ex)+'"></p><p><button type="button" class="btn alt seg" hidden>'+L('Próxima →','Next →')+'</button></p>';cont.textContent=(i+1)+L(' de ',' of ')+itens.length;delete caixa.dataset.feito;ligaQuiz(caixa,function(ok){if(ok)pts++;var s2=$('.seg',caixa);s2.hidden=false;s2.addEventListener('click',function(){i++;prox();});s2.focus();});};prox();}
var mistura=function(a){return a.slice().sort(function(){return Math.random()-.5;});};if(tipoF==='ident'){var frs=JSON.parse($('#dados-ident').textContent),tps=JSON.parse($('#dados-tipos').textContent);sequencia($('#id-q'),$('#id-n'),mistura(frs),function(f){var outras=mistura(tps.filter(function(t){return t!==f[1];})).slice(0,3);return{p:f[0],ops:mistura(outras.concat([f[1]])),certa:f[1],ex:f[2]};});}
